#include <bits/stdc++.h>
using namespace std;

int main() {
    long long k;
    cin >> k;

    if (k < 10) {
        cout << k;
        return 0;
    }

    long long digits = 1;
    long long start = 1;
    __int128 count = 9;

    while ((__int128)k > count * digits) {
        k -= (long long)(count * digits);
        ++digits;
        start *= 10;
        count *= 10;
    }

    long long number = start + (k - 1) / digits;
    int index = (k - 1) % digits;

    cout << to_string(number)[index];
    return 0;
}

