#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long k;
    cin >> k;

    if (k < 10) {
        cout << k;
        return 0;
    }

    __int128 pos = k;
    __int128 start = 1;
    __int128 count = 9;
    int length = 1;

    while (pos > count * length) {
        pos -= count * length;
        start *= 10;
        count *= 10;
        ++length;
    }

    __int128 number = start + (pos - 1) / length;
    int index = static_cast<int>((pos - 1) % length);

    string s;
    do {
        s.push_back('0' + number % 10);
        number /= 10;
    } while (number);
    reverse(s.begin(), s.end());

    cout << s[index];
    return 0;
}

